BEGIN;

-- Ficha de Mario Rivera.
--
-- occupations añade bandleader (Salsa Refugees, Mario Rivera Sextet). instruments:
-- saxophone, flute, trumpet, piano, drums, congas (vocabulario existente; vibráfono y
-- timbales no tienen valor en el catálogo todavía).
-- «El Comandante»: 1993 (Miami Herald), 1994 (discografía de Wikipedia), 1996 (texto
-- de Wikipedia, Jazz Latino). Escrito "a mediados de los noventa".
-- Nombre legal Mario Antonio Rivera Manzanillo solo en Wikipedia: no añadido.
-- Fuera: la causa médica de su muerte.

UPDATE artists SET occupations = '["composer","saxophonist","arranger","bandleader"]'::jsonb, instruments = ARRAY['saxophone', 'flute', 'trumpet', 'piano', 'drums', 'congas']::text[] WHERE slug = 'mario-rivera';

